"""Builds the assembly fixtures and what the metadata oracle says about them.

    python tests/fixtures/assemblies/build.py

Needs the .NET SDK 10 or newer, which `cargo test` does not. Each project in
src/ is compiled in a temporary copy, so no bin/ or obj/ lands in the
repository, and its assembly is written here as <Name>.dll. Then
tools/metadata-oracle reads them all with System.Reflection.Metadata and its
output is written to oracle.jsonl. customs's tests compare its own reader with
that file.

Wide.dll is generated: enough long method names to push the string heap over
64 KiB, so that its indexes are four bytes wide, plus a module initialiser and
a P/Invoke, which a reader that ignores the wide flag would misread.
Standard library only.
"""

import pathlib
import shutil
import subprocess
import sys
import tempfile

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parent.parent.parent
ORACLE = ROOT / "tools" / "metadata-oracle"
PROJECTS = ["ModuleInit", "PInvoke", "Plain", "Marker", "Wide"]


def wide_source(count=2500):
    methods = "\n".join(
        f"    public static int Method{i:05}_with_a_long_name_to_fill_the_heap() => {i};"
        for i in range(count)
    )
    return f"""// Generated by build.py. Do not edit.

using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace Fixture.Wide;

public static class Many
{{
{methods}
}}

public static class Start
{{
    internal static int Count;

    [ModuleInitializer]
    internal static void Run() => Count = 1;

    [DllImport("kernel32.dll")]
    internal static extern nint VirtualAlloc(nint address, nuint size, uint type, uint protect);
}}
"""


def run(command, cwd):
    print("+", " ".join(str(c) for c in command), flush=True)
    subprocess.run(command, cwd=cwd, check=True)


def main():
    with tempfile.TemporaryDirectory() as temp:
        work = pathlib.Path(temp) / "src"
        shutil.copytree(HERE / "src", work)
        (work / "Wide" / "Wide.cs").write_text(wide_source(), encoding="utf-8")
        for name in PROJECTS:
            out = pathlib.Path(temp) / "out" / name
            run(
                ["dotnet", "build", str(work / name / f"{name}.csproj"), "-c", "Release",
                 "-o", str(out), "--nologo", "-v", "quiet"],
                cwd=work,
            )
            shutil.copyfile(out / f"{name}.dll", HERE / f"{name}.dll")
    result = subprocess.run(
        ["dotnet", "run", "--project", str(ORACLE), "-c", "Release", "--"]
        + [str(HERE / f"{name}.dll") for name in PROJECTS],
        cwd=ROOT,
        check=True,
        capture_output=True,
    )
    (HERE / "oracle.jsonl").write_bytes(result.stdout.replace(b"\r\n", b"\n"))
    print(f"wrote {len(PROJECTS)} assemblies and oracle.jsonl", file=sys.stderr)


if __name__ == "__main__":
    main()
